// What Enter inserts in a multiline box: LF (the default), CR or CRLF; anything else throws std::invalid_argument.
template <typename Declaring>
struct TextBoxNewlineSequenceCapability {
    PropertyCell<std::string, TextBoxNewlineSequenceCapability<Declaring>> newline_sequence{std::string{"\n"}};

    static void assign(TextBoxNewlineSequenceCapability& capability, std::string incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.newline_sequence), incoming);
        if (!capability.newline_sequence.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.newline_sequence));
    }
};

// Whether Tab inserts a tab in a multiline box (AcceptsTab) instead of moving the focus.
template <typename Declaring>
struct TextBoxAcceptsTabCapability {
    PropertyCell<bool, TextBoxAcceptsTabCapability<Declaring>> accepts_tab{};

    static void assign(TextBoxAcceptsTabCapability& capability, bool incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.accepts_tab), incoming);
        if (!capability.accepts_tab.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.accepts_tab));
    }
};

// In a single-line box Enter is the box's own only while it has something to accept: an open suggestion list or appended completion, or an input-method composition; otherwise Enter goes on to the containers and the window's accept button. A box that is an edit session (a search field, an in-place editor) opts in with accepts_enter: plain Enter with nothing else to accept then raises committed() and stops there. Off by default. A multi-line box always takes Enter to insert newline_sequence.
template <typename Declaring>
struct TextBoxAcceptsEnterCapability {
    PropertyCell<bool, TextBoxAcceptsEnterCapability<Declaring>> accepts_enter{};

    static void assign(TextBoxAcceptsEnterCapability& capability, bool incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.accepts_enter), incoming);
        if (!capability.accepts_enter.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.accepts_enter));
    }
};

// Escape is the box's own only while it has something to cancel: an open suggestion list or appended completion, an input-method composition or a selection drag; otherwise Escape goes on to the containers, menus and the window's cancel button. A box that is an edit session opts in with accepts_escape: plain Escape with nothing else to cancel then raises cancelled() and stops there. Off by default.
template <typename Declaring>
struct TextBoxAcceptsEscapeCapability {
    PropertyCell<bool, TextBoxAcceptsEscapeCapability<Declaring>> accepts_escape{};

    static void assign(TextBoxAcceptsEscapeCapability& capability, bool incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.accepts_escape), incoming);
        if (!capability.accepts_escape.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.accepts_escape));
    }
};

// The most Unicode scalars a user edit, a paste or a semantic set-value may leave (MaxLength); zero admits any text that fits the store. A write does not truncate the text. A view onto the editing engine; more than 16 Mi throws std::out_of_range.
template <typename Declaring>
struct TextBoxMaximumLengthCapability {
    PropertyView<std::size_t, TextBoxMaximumLengthCapability<Declaring>> maximum_length;

    static void assign(TextBoxMaximumLengthCapability& capability, std::size_t incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.write_view(std::as_const(capability.maximum_length), std::move(incoming));
    }

    static std::size_t read(const TextBoxMaximumLengthCapability& capability) {
        const Declaring& control = static_cast<const Declaring&>(capability);
        std::size_t current = control.read_view(capability.maximum_length);
        return current;
    }
};

// The character shown for each character of the text (PasswordChar); U'\0' for none. Throws std::invalid_argument in a multiline box or for anything but one printable Unicode scalar.
