// How completions are offered (AutoCompleteMode): none, suggest (a list under the box), append (the rest of the first match, selected) or both. Auto-complete acts only in a single-line, unmasked, writable box with no edit filter; otherwise the settings are kept and do nothing. Matching is by prefix, ignoring ASCII case unless auto_complete_case_sensitive.
template <typename Declaring>
struct TextBoxAutoCompleteModeCapability {
    PropertyCell<AutoCompleteMode, TextBoxAutoCompleteModeCapability<Declaring>> auto_complete_mode{AutoCompleteMode::none};

    static void assign(TextBoxAutoCompleteModeCapability& capability, AutoCompleteMode incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.auto_complete_mode), incoming);
        if (!capability.auto_complete_mode.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.auto_complete_mode));
    }
};

// Where completion candidates come from (AutoCompleteSource). list_items throws std::invalid_argument: a TextBox has no list (an editable ComboBox offers its items through its own setting).
template <typename Declaring>
struct TextBoxAutoCompleteSourceCapability {
    PropertyCell<AutoCompleteSource, TextBoxAutoCompleteSourceCapability<Declaring>> auto_complete_source{AutoCompleteSource::none};

    static void assign(TextBoxAutoCompleteSourceCapability& capability, AutoCompleteSource incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.auto_complete_source), incoming);
        if (!capability.auto_complete_source.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.auto_complete_source));
    }
};

// The candidates for AutoCompleteSource::custom_source (AutoCompleteCustomSource). Never null: a new box owns an empty collection. Assigning one shares it (see AutoCompleteStringCollection); null throws std::invalid_argument.
template <typename Declaring>
struct TextBoxAutoCompleteCustomSourceCapability {
    PropertyCell<std::shared_ptr<AutoCompleteStringCollection>, TextBoxAutoCompleteCustomSourceCapability<Declaring>> auto_complete_custom_source{std::make_shared<AutoCompleteStringCollection>()};

    static void assign(TextBoxAutoCompleteCustomSourceCapability& capability, std::shared_ptr<AutoCompleteStringCollection> incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.auto_complete_custom_source), incoming);
        if (!capability.auto_complete_custom_source.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.auto_complete_custom_source));
    }
};

